function territorySignature(){const st=gameState(),own=Object.entries(st.ownership||{}).sort((a,b)=>String(a[0]).localeCompare(String(b[0]))),admins=(st.administrations||[]).map(a=>[a.id,a.parentEntityId,(a.provinceIds||[]).map(String).sort()]).sort((a,b)=>String(a[0]).localeCompare(String(b[0])));const nations=(st.nations||[]).map(n=>[n.id,n.name]).sort((a,b)=>String(a[0]).localeCompare(String(b[0])));return JSON.stringify([own,admins,nations])}
function dissolveGroupFeatures(){
 const groups=new Map();
 for(const f of gFeatures){
  const pid=String(f.properties.__id),own=owner(pid);
  let key,kind,id,label;
  if(own){const n=nation(own);key='nation:'+own;kind='nation';id=own;label=n?.name||own}
  else{key='unowned';kind='unowned';id='__UNOWNED__';label='Territorio Baldío'}
  if(!groups.has(key))groups.set(key,{kind,id,label,features:[]});
  groups.get(key).features.push(f);
 }
 return [...groups.entries()];
}
// Agrupa las provincias en una única feature MultiPolygon por entidad.
// No ejecuta una unión booleana: evita los fallos de priority queue de polygon-clipping.
// Las fronteras interiores quedan invisibles al dibujar cada entidad con su propio color de trazo.
async function makeDissolvedFeatures(token){
 const groups=dissolveGroupFeatures(),out=[];
 for(let gi=0;gi<groups.length;gi++){
  if(token!==gDissolveToken)return null;
  const [,group]=groups[gi],polygons=[];
  for(let fi=0;fi<group.features.length;fi++){
   const geom=group.features[fi].geometry;
   if(!geom)continue;
   if(geom.type==='Polygon'&&Array.isArray(geom.coordinates)&&geom.coordinates.length)polygons.push(geom.coordinates);
   else if(geom.type==='MultiPolygon'&&Array.isArray(geom.coordinates))for(const poly of geom.coordinates)if(Array.isArray(poly)&&poly.length)polygons.push(poly);
   // Cede el hilo periódicamente para que la interfaz siga respondiendo con 12.103 provincias.
   if(fi>0&&fi%300===0){if(token!==gDissolveToken)return null;await new Promise(resolve=>setTimeout(resolve,0));}
  }
  if(!polygons.length)continue;
  const geometry={type:'MultiPolygon',coordinates:polygons};
  out.push({type:'Feature',properties:{__entityId:group.id,__kind:group.kind,__label:group.label},geometry});
  await new Promise(resolve=>setTimeout(resolve,0));
 }
 return out;
}
function dissolvedFeatureStyle(f){const p=f.properties||{};let color='#777d83',opacity=.55;if(p.__kind==='nation'){color=nation(p.__entityId)?.color||'#d8d8d6';opacity=.78}else if(p.__kind==='administration'){const a=administrationById(p.__entityId);color=a?.color||'#b79a68';opacity=.76}return{stroke:false,color,weight:0,opacity:0,fillColor:color,fillOpacity:opacity,lineCap:'round',lineJoin:'round',interactive:false}}
