function forceNumber(v){const n=Number(v);return Number.isFinite(n)?Math.max(0,n):0}
function forceMetricSet(obj){const labels={discipline:'Disciplina',command:'Mando',logistics:'Logística',morale:'Moral',equipment:'Equipamiento'};return Object.entries(labels).map(([k,label])=>({key:k,label,value:Math.max(0,Math.min(100,Number(obj?.[k]??50)||0))}))}
function weightedForceMetrics(formations){const keys=['discipline','command','logistics','morale','equipment'];const total=formations.reduce((a,f)=>a+forceNumber(f.troops),0);const result={};keys.forEach(k=>{result[k]=total?formations.reduce((a,f)=>a+Number(f.metrics?.[k]??50)*forceNumber(f.troops),0)/total:50});return result}
function forceGrade(metrics){const m=metrics||{};return Math.round((Number(m.discipline??50)*.20)+(Number(m.command??50)*.20)+(Number(m.logistics??50)*.25)+(Number(m.morale??50)*.15)+(Number(m.equipment??50)*.20))}
function forceBars(metrics){return forceMetricSet(metrics).map(m=>`<div><div class="force-bar-head"><span>${m.label}</span><b>${Math.round(m.value)}/100</b></div><div class="force-bar"><span style="width:${m.value}%"></span></div></div>`).join('')}
function formatTroops(v){return forceNumber(v).toLocaleString('es-ES')}
function locateFormation(f){const wanted=[...(f.provinceIds||[]),...(f.provinces||[]),...(f.provinceNames||[]),...(Array.isArray(f.deployment)?f.deployment:[])].map(String);if(f.provinceId)wanted.push(String(f.provinceId));if(f.location)wanted.push(String(f.location));const matches=gFeatures.filter(feature=>wanted.some(w=>w===String(feature.properties.__id)||w.toLowerCase()===String(feature.properties.__name).toLowerCase()));if(!matches.length){alert('No se ha encontrado esa localización en la cartografía cargada. Comprueba provinceIds/provinces o el nombre de la provincia en el JSON.');return}ensureProvinceLayer();if(gDissolvedLayer&&gmap.hasLayer(gDissolvedLayer))gmap.removeLayer(gDissolvedLayer);if(!gmap.hasLayer(gLayer))gLayer.addTo(gmap);const layerList=[];if(gLayer)gLayer.eachLayer(l=>{if(matches.some(f=>f.properties.__id===l.feature?.properties?.__id))layerList.push(l)});if(layerList.length){const group=L.featureGroup(layerList);gmap.fitBounds(group.getBounds(),{padding:[50,50],maxZoom:7});layerList.forEach(l=>l.setStyle({color:'#fff',weight:2.5,fillOpacity:1}));setTimeout(()=>refreshGameMapStyles(),3500);$('armedForcesModal').classList.remove('show');$('gameStatus').textContent='Localización militar: '+(f.location||matches.map(x=>x.properties.__name).join(', '))}}
function renderArmedForces(){const n=nation(gGame.player),data=gGame.armedForces?.[gGame.player],branches=data?.branches||[];$('armedForcesModalTitle').textContent='Fuerzas Armadas · '+(n?.name||'');const body=$('armedForcesModalBody');if(!branches.length){body.innerHTML='<div class="force-empty">Este Estado todavía no tiene ramas militares definidas.</div>';$('armedForcesModal').classList.add('show');return}const totalTroops=branches.reduce((sum,b)=>(sum+(b.formations||[]).reduce((a,f)=>a+forceNumber(f.troops),0)),0);const allFormations=branches.flatMap(b=>b.formations||[]);const nationalMetrics=weightedForceMetrics(allFormations);const nationalGrade=forceGrade(nationalMetrics);body.innerHTML=`<div class="force-summary"><div class="force-stat"><small>Efectivos totales</small><b>${formatTroops(totalTroops)}</b></div><div class="force-stat"><small>Ramas militares</small><b>${branches.length}</b></div><div class="force-stat"><small>Estado militar nacional</small><b>${nationalGrade}/100</b></div></div><div class="force-branch-tabs" id="forceBranchTabs"></div><div id="forceBranchContent"></div>`;const tabs=body.querySelector('#forceBranchTabs'),content=body.querySelector('#forceBranchContent');branches.forEach((branch,i)=>{const b=document.createElement('button');b.textContent=(branch.icon?branch.icon+' ':'')+(branch.name||'Rama '+(i+1));b.className=i===0?'active':'';b.onclick=()=>{tabs.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));drawBranch(i)};tabs.appendChild(b)});function drawBranch(i){const branch=branches[i],formations=branch.formations||[],troops=formations.reduce((a,f)=>a+forceNumber(f.troops),0),metrics=weightedForceMetrics(formations),grade=forceGrade(metrics);let html=`<div class="force-branch-overview"><div class="force-grade"><strong>${grade}/100</strong><small>Estado de ${safe(branch.name||'la rama')}</small><div class="hint">${formatTroops(troops)} efectivos</div></div><div class="force-bars">${forceBars(metrics)}</div></div><h3>Formaciones y despliegues</h3>`;if(!formations.length)html+='<div class="force-empty">No hay formaciones definidas en esta rama.</div>';formations.forEach((f,j)=>{const fm=f.metrics||{},composition=f.composition||{};const gradeF=forceGrade(fm);const entries=Object.entries(composition).filter(([k,v])=>forceNumber(v)>0);html+=`<details class="force-formation"><summary><div class="formation-main"><b>${safe(f.name||'Formación '+(j+1))}</b><small>${safe(f.headquarters||f.location||'Localización no especificada')} · ${safe(f.status||'Estado no especificado')}</small></div><span class="formation-count">${formatTroops(f.troops)}</span><span class="pill">${gradeF}/100</span></summary><div class="formation-detail"><div class="formation-meta"><span>Cuartelamiento: <b>${safe(f.headquarters||'No especificado')}</b></span><span>Despliegue: <b>${safe((f.deployment||f.provinceNames||f.provinces||[]).join? (f.deployment||f.provinceNames||f.provinces||[]).join(', '):(f.deployment||'No especificado'))}</b></span></div><div class="formation-bars">${forceBars(fm)}</div><b>Composición</b><div class="composition-grid">${entries.length?entries.map(([k,v])=>`<div class="composition-item"><small>${safe(k.replace(/([A-Z])/g,' $1').replace(/[_-]/g,' '))}</small><b>${formatTroops(v)}</b></div>`).join(''):'<div class="hint">Sin composición desglosada.</div>'}</div><button class="state-action" data-locate-force="${i}:${j}">⌖ Ir a localización</button></div></details>`});content.innerHTML=html;content.querySelectorAll('[data-locate-force]').forEach(btn=>btn.onclick=()=>{const [bi,fi]=btn.dataset.locateForce.split(':').map(Number);locateFormation(branches[bi].formations[fi])})}drawBranch(0);$('armedForcesModal').classList.add('show')}
