function safe(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function eventIcon(e){
 const allowed=['🪙','🏭','🛤️','🏗️','⚔️','🛡️','⚓','🚢','🤝','👁️','🔥','👑','📦','📜','🌾','📖','🏛️','🗺️','⚖️','🕊️'];
 if(e.icon&&allowed.includes(e.icon))return e.icon;
 const key=String(e.category||e.type||'').toLowerCase();
 const rules=[[/econom|finanz|moneda|fiscal/,'🪙'],[/industr|fábr|fabric/,'🏭'],[/infraestruct|ferrocarr|ferrocar|carreter|obra|constru/,'🏗️'],[/ejércit|militar|guerra|batalla|reclut|defensa/,'⚔️'],[/armada|naval|marítim|flota/,'⚓'],[/diplom|tratado|alianza|embajad/,'🤝'],[/espion|inteligencia|agente/,'👁️'],[/rebel|revuelta|levantamiento|revolu/,'🔥'],[/polític|corona|gobierno|monarqu|elecci/,'👑'],[/comerci|mercado|export|import/,'📦'],[/cien|investig|descubrim|tecnolog/,'📜'],[/agric|cosecha|cultivo/,'🌾'],[/histó|fundación|fundacion|anivers/,'📖'],[/constit|ley|reforma|institu/,'⚖️'],[/paz|alto el fuego/,'🕊️']];
 for(const [re,icon] of rules)if(re.test(key))return icon;
 return e.type==='history'?'📖':'🗺️';
}
function appendEventBlock(parent,b){if(!b||typeof b!=='object')return null;if(b.type==='image'&&b.url){const fig=document.createElement('figure'),im=document.createElement('img');im.src=b.url;im.alt=b.alt||'';fig.appendChild(im);if(b.caption){const cap=document.createElement('figcaption');cap.textContent=b.caption;fig.appendChild(cap)}parent.appendChild(fig);return fig}if(b.type==='heading'){const h=document.createElement('h3');h.textContent=b.text||'';parent.appendChild(h);return h}if(b.type==='list'&&Array.isArray(b.items)){const ul=document.createElement('ul');b.items.forEach(t=>{const li=document.createElement('li');li.textContent=t;ul.appendChild(li)});parent.appendChild(ul);return ul}if(b.text){const para=document.createElement('p');para.textContent=b.text;parent.appendChild(para);return para}return null}
function openEvent(e,review=false){$('eventModalMeta').textContent=(e.date||gGame.date)+' · '+(e.type==='history'?'HISTÓRICO':String(e.type||'TURNO').toUpperCase());$('eventModalTitle').textContent=e.title||'Acontecimiento';const body=$('eventModalBody');body.innerHTML='';const blocks=Array.isArray(e.content)?e.content:null;if(blocks){blocks.forEach(b=>{if(b.type==='row'||b.type==='split'){const row=document.createElement('div');row.className='event-split '+(b.imagePosition==='right'?'image-right':'image-left');const img=b.image||{},imageBlock={type:'image',url:img.url||b.url,alt:img.alt||b.alt,caption:img.caption||b.caption};const figure=document.createElement('div');appendEventBlock(figure,imageBlock);const textWrap=document.createElement('div');textWrap.className='event-split-text';const textBlocks=Array.isArray(b.textBlocks)?b.textBlocks:(Array.isArray(b.blocks)?b.blocks:[{type:'text',text:b.text||''}]);textBlocks.forEach(x=>appendEventBlock(textWrap,x));if(b.imagePosition==='right'){row.appendChild(textWrap);row.appendChild(figure)}else{row.appendChild(figure);row.appendChild(textWrap)}body.appendChild(row)}else appendEventBlock(body,b)})}else{if(e.image){const im=document.createElement('img');im.src=e.image;im.alt=e.imageAlt||'';body.appendChild(im)}String(e.text||'').split(/\n\s*\n/).forEach(t=>{const para=document.createElement('p');para.textContent=t;body.appendChild(para)})}$('eventReviewFoot').classList.toggle('hidden',!review);$('eventModal').classList.add('show')}
function showNextTurnEvent(){if(turnReviewIndex>=turnReviewQueue.length){finishTurnEventReview();return}const e=turnReviewQueue[turnReviewIndex];openEvent(e,true);$('eventReviewCount').textContent=`Acontecimiento ${turnReviewIndex+1} de ${turnReviewQueue.length}`;$('nextReviewEvent').textContent=turnReviewIndex===turnReviewQueue.length-1?'Finalizar →':'Siguiente evento →'}
function finishTurnEventReview(){turnReviewQueue=[];turnReviewIndex=0;$('eventModal').classList.remove('show');$('eventReviewFoot').classList.add('hidden')}
$('nextReviewEvent').onclick=()=>{turnReviewIndex++;showNextTurnEvent()};$('finishEventReview').onclick=finishTurnEventReview;
function renderChronicle(){const list=$('chronicleList');list.innerHTML='';(gGame.events||[]).slice().reverse().forEach(e=>{const card=document.createElement('article');card.className='event-card';card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label','Abrir acontecimiento: '+(e.title||''));const text=String(e.text||'');card.innerHTML=`<div class="event-icon" aria-hidden="true">${eventIcon(e)}</div><div class="event-meta">${safe(e.date||gGame.date)} · ${safe(e.type==='history'?'HISTÓRICO':String(e.type||'TURNO').toUpperCase())}</div><b>${safe(e.title)}</b><p>${safe(text)}</p><span class="more-indicator" aria-hidden="true">+</span>`;list.appendChild(card);requestAnimationFrame(()=>{const para=card.querySelector('p');if(para&&(para.scrollHeight>para.clientHeight+1||para.scrollWidth>para.clientWidth+1||card.scrollHeight>card.clientHeight+1))card.classList.add('has-overflow')});card.addEventListener('click',()=>openEvent(e));card.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();openEvent(e)}});})}
function saveGame(){
 if(!gGame)return;
 const games=readJSON(keys.games,[]),idx=games.findIndex(x=>x.id===gGame.id);
 if(idx>=0)games[idx]=gGame;else games.push(gGame);
 localStorage.setItem(keys.games,JSON.stringify(games));
 const blob=new Blob([JSON.stringify(gGame,null,2)],{type:'application/json'});
 const url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download=(String(gGame.name||'partida').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^a-z0-9-_]+/gi,'-').replace(/^-|-$/g,'')||'partida')+'.json';
 document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
 $('gameStatus').textContent='Partida exportada · '+new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'});
 alert('Partida descargada como archivo JSON. Guárdala en tu ordenador o en tu nube; podrás importarla al volver. También queda una copia local en este navegador.');
}
$('saveGameBtn').onclick=saveGame;
$('loadGameBtn').onclick=()=>{const games=readJSON(keys.games,[]),sel=$('savedGameSelect');sel.innerHTML='<option value="">Selecciona una partida</option>';games.forEach(g=>{const o=document.createElement('option');o.value=g.id;o.textContent=g.name+' · '+g.date;sel.appendChild(o)});$('loadGameModal').classList.add('show')};
