function entityCreationLabel(entity){const t=entity.entityType||entity.type||'political_entity';const labels={viceroyalty:'Virreinato',governorate:'Gobernación',colony:'Colonia',protectorate:'Protectorado',autonomous_region:'Región autónoma',administrative_region:'Región administrativa',kingdom:'Reino',duchy:'Ducado',principality:'Principado',state:'Estado'};return labels[t]||String(t).replace(/[_-]/g,' ').replace(/^./,c=>c.toUpperCase())}
function beginEntityCreationQueue(items){pendingEntityQueue=items.map(x=>({...x}));pendingEntityIndex=0;beginNextEntityCreation()}
function beginNextEntityCreation(){if(pendingEntityIndex>=pendingEntityQueue.length){pendingEntityDraft=null;pendingEntityProvinceIds.clear();$('entityCreationPanel').classList.add('hidden');refreshGameMapStyles();renderCountry();renderGlobalRank();$('gameStatus').textContent='Entidades políticas creadas. Recuerda guardar la partida.';if(turnReviewQueue.length){turnReviewIndex=0;showNextTurnEvent()}return}pendingEntityDraft=pendingEntityQueue[pendingEntityIndex];pendingEntityProvinceIds=new Set();const e=pendingEntityDraft;$('entityCreationTitle').textContent='Delimitar '+(e.name||'nueva entidad');$('entityCreationStep').textContent=(pendingEntityIndex+1)+' / '+pendingEntityQueue.length;$('entityCreationDescription').textContent=entityCreationLabel(e)+' · Selecciona en el mapa las provincias que formarán esta entidad. Las provincias elegidas pasarán a su control.';$('entityProvinceCount').textContent='0';$('entityCreationColor').value=/^#[0-9a-f]{6}$/i.test(e.color||'')?e.color:'#b79a68';$('entityCreationFlag').value=e.flag||'';$('entityCreationCoat').value=e.coat||'';$('entityCreationFlagFile').value='';$('entityCreationCoatFile').value='';pendingEntityFlagData='';pendingEntityCoatData='';$('entityCreationPanel').classList.remove('hidden');$('gameStatus').textContent='Delimitando '+(e.name||'nueva entidad')+'. Haz clic en las provincias del mapa.';refreshGameMapStyles()}
function togglePendingEntityProvince(pid){if(!pendingEntityDraft)return;const layer=gProvinceLayerById.get(String(pid)),f=layer?.feature;if(!f)return;const currentOwner=owner(pid),targetOverlord=pendingEntityDraft.overlord||pendingEntityDraft.parentEntityId||null;if(targetOverlord&&currentOwner!==targetOverlord){$('gameStatus').textContent='Esta provincia no pertenece a la entidad superior indicada. Solo puedes seleccionar provincias de '+(nation(targetOverlord)?.name||targetOverlord)+'.';return}if(pendingEntityProvinceIds.has(pid))pendingEntityProvinceIds.delete(pid);else pendingEntityProvinceIds.add(pid);$('entityProvinceCount').textContent=String(pendingEntityProvinceIds.size);if(layer)layer.setStyle(gameFeatureStyle(f))}
function finalizePendingEntity(){if(!pendingEntityDraft)return;if(!pendingEntityProvinceIds.size){alert('Selecciona al menos una provincia para crear la entidad.');return}const e=pendingEntityDraft,st=gameState(),id=String(e.id||('ENT-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6)));if(st.nations.some(n=>n.id===id)){alert('Ya existe una entidad con el identificador '+id+'. Corrige el id en el JSON.');return}const status=['sovereign','semi','non'].includes(e.status)?e.status:(e.sovereignty==='sovereign'?'sovereign':'non');const parent=e.overlord||e.parentEntityId||null;if(parent&&!st.nations.some(n=>n.id===parent)){alert('La entidad superior indicada ('+parent+') no existe en esta fecha.');return}const entity={id,name:String(e.name||'Nueva entidad'),entityType:String(e.entityType||e.type||'political_entity'),status,overlord:parent,color:$('entityCreationColor').value,flag:pendingEntityFlagData||$('entityCreationFlag').value.trim()||null,coat:pendingEntityCoatData||$('entityCreationCoat').value.trim()||null,leader:e.leader||'',portrait:e.portrait||'',government:e.government||'',...(e.description?{description:String(e.description)}:{}),...(e.attributes&&typeof e.attributes==='object'?{attributes:e.attributes}:{})};st.nations.push(entity);st.ownership=st.ownership||{};for(const pid of pendingEntityProvinceIds)st.ownership[pid]=id;if(!st.capitals)st.capitals={};if(e.capitalProvinceId&&pendingEntityProvinceIds.has(String(e.capitalProvinceId)))st.capitals[id]=String(e.capitalProvinceId);gSelected=id;pendingEntityIndex++;beginNextEntityCreation()}
function readEntityImage(file,callback){if(!file)return;if(!file.type.startsWith('image/')){alert('Selecciona un archivo de imagen.');return}if(file.size>5*1024*1024){alert('La imagen no puede superar los 5 MB.');return}const reader=new FileReader();reader.onload=()=>callback(String(reader.result||''));reader.onerror=()=>alert('No se pudo leer la imagen.');reader.readAsDataURL(file)}
$('entityCreationFlagFile').onchange=e=>readEntityImage(e.target.files?.[0],v=>{pendingEntityFlagData=v;$('entityCreationFlag').value='';});$('entityCreationCoatFile').onchange=e=>readEntityImage(e.target.files?.[0],v=>{pendingEntityCoatData=v;$('entityCreationCoat').value='';});$('entityCreationFlag').oninput=()=>{pendingEntityFlagData='';};$('entityCreationCoat').oninput=()=>{pendingEntityCoatData='';};
$('entityCreationSave').onclick=finalizePendingEntity;$('entityCreationCancel').onclick=()=>{if(!confirm('¿Cancelar la creación de esta entidad? Las provincias seleccionadas no cambiarán de propietario y se omitirán las demás creaciones pendientes.'))return;pendingEntityDraft=null;pendingEntityQueue=[];pendingEntityProvinceIds.clear();$('entityCreationPanel').classList.add('hidden');refreshGameMapStyles();$('gameStatus').textContent='Creación de entidades cancelada.';if(turnReviewQueue.length){turnReviewIndex=0;showNextTurnEvent()}};

function applyMetricSet(target,patch,label){
 if(!patch||typeof patch!=='object')return;
 for(const k of ['stability','economy','support','military','administration']){
  if(patch[k]!==undefined){const v=Number(patch[k]);if(!Number.isFinite(v)||v<0||v>100)throw new Error(label+': '+k+' debe estar entre 0 y 100.');target[k]=v;}
 }
}
$('applyTurnBtn').onclick=()=>{
 if(!gGame){alert('No hay una partida activa.');return}
 let payload;try{payload=JSON.parse($('turnPayload').value)}catch(e){alert('El JSON no es válido: '+e.message);return}
 if(!payload||typeof payload!=='object'||Array.isArray(payload)){alert('El contenido debe ser un objeto JSON.');return}
 const draft=JSON.parse(JSON.stringify(gGame));
 try{
  const state=draft.scenario?.dates?.[draft.date];if(!state)throw new Error('No se encuentra el estado territorial de la fecha actual.');
  const knownNations=new Set((state.nations||[]).map(n=>n.id));
  if(payload.date){if(!/^\d{4}(-\d{2}(-\d{2})?)?$/.test(String(payload.date)))throw new Error('La fecha debe tener formato AAAA, AAAA-MM o AAAA-MM-DD.');draft.date=String(payload.date);if(!draft.scenario.dates[draft.date])draft.scenario.dates[draft.date]=JSON.parse(JSON.stringify(state));}
  if(payload.turn!==undefined){const t=Number(payload.turn);if(!Number.isInteger(t)||t<draft.turn)throw new Error('El número de turno debe ser un entero igual o superior al turno actual.');draft.turn=t;}else draft.turn=(draft.turn||0)+1;
  const activeState=draft.scenario.dates[draft.date];
  const nationIds=new Set((activeState.nations||[]).map(n=>n.id));
  if(payload.metrics){draft.metrics=draft.metrics||{stability:68,economy:55,support:62,military:48,administration:60};applyMetricSet(draft.metrics,payload.metrics,'Indicadores del jugador')}
  if(payload.subjectMetrics){draft.subjectMetrics=draft.subjectMetrics||{};for(const [id,patch] of Object.entries(payload.subjectMetrics)){if(!nationIds.has(id))throw new Error('País desconocido en subjectMetrics: '+id);draft.subjectMetrics[id]=draft.subjectMetrics[id]||{stability:64,economy:51,support:59,military:46,administration:54};applyMetricSet(draft.subjectMetrics[id],patch,'Indicadores de '+id)}}
  if(payload.countryMetrics){draft.countryMetrics=draft.countryMetrics||{};for(const [id,patch] of Object.entries(payload.countryMetrics)){if(!nationIds.has(id))throw new Error('País desconocido en countryMetrics: '+id);draft.countryMetrics[id]=draft.countryMetrics[id]||{};applyMetricSet(draft.countryMetrics[id],patch,'Indicadores de '+id)}}
  if(payload.publicEstimates){draft.publicEstimates=draft.publicEstimates||{};for(const [id,patch] of Object.entries(payload.publicEstimates)){if(!nationIds.has(id))throw new Error('País desconocido en publicEstimates: '+id);const clean={...(draft.publicEstimates[id]||{})};for(const k of ['economy','military'])if(patch[k]!==undefined){const v=Number(patch[k]);if(!Number.isFinite(v)||v<0||v>100)throw new Error('Estimación pública '+k+' debe estar entre 0 y 100.');clean[k]=v;}draft.publicEstimates[id]=clean;}}

  if(payload.territorialChanges){if(!Array.isArray(payload.territorialChanges))throw new Error('territorialChanges debe ser una lista.');for(const change of payload.territorialChanges){const pid=String(change.provinceId??change.province??'');if(!pid)throw new Error('Cada cambio territorial necesita provinceId.');if(change.ownerId!==null&&!nationIds.has(change.ownerId))throw new Error('País propietario desconocido: '+change.ownerId);activeState.ownership=activeState.ownership||{};if(change.ownerId===null)delete activeState.ownership[pid];else activeState.ownership[pid]=change.ownerId;}}
  if(payload.capitals){for(const [id,provinceId] of Object.entries(payload.capitals)){if(!nationIds.has(id))throw new Error('País desconocido en capitals: '+id);activeState.capitals=activeState.capitals||{};activeState.capitals[id]=provinceId;}}
  if(payload.nationUpdates){for(const [id,patch] of Object.entries(payload.nationUpdates)){const n=(activeState.nations||[]).find(x=>x.id===id);if(!n)throw new Error('País desconocido en nationUpdates: '+id);for(const k of ['leader','government','name','status','overlord','color','flag','coat','portrait','entityType'])if(patch[k]!==undefined)n[k]=patch[k];}}
  if(payload.dynasties){draft.dynasties=draft.dynasties||{};for(const [id,data] of Object.entries(payload.dynasties)){if(!nationIds.has(id))throw new Error('País desconocido en dynasties: '+id);if(!data||typeof data!=='object')throw new Error('Cada dinastía debe ser un objeto.');draft.dynasties[id]=data;}}
  if(payload.parliaments){draft.parliaments=draft.parliaments||{};for(const [id,data] of Object.entries(payload.parliaments)){if(!nationIds.has(id))throw new Error('País desconocido en parliaments: '+id);if(!Array.isArray(data))throw new Error('Los parlamentos de cada país deben ser una lista.');draft.parliaments[id]=data;}}
  if(payload.governments){draft.governments=draft.governments||{};for(const [id,data] of Object.entries(payload.governments)){if(!nationIds.has(id))throw new Error('País desconocido en governments: '+id);if(!data||typeof data!=='object')throw new Error('Cada gobierno debe ser un objeto.');draft.governments[id]=data;}}
  if(payload.armedForces){draft.armedForces=draft.armedForces||{};for(const [id,data] of Object.entries(payload.armedForces)){if(!nationIds.has(id))throw new Error('País desconocido en armedForces: '+id);if(!data||!Array.isArray(data.branches))throw new Error('armedForces.'+id+' debe contener branches como lista.');for(const branch of data.branches){if(!Array.isArray(branch.formations))throw new Error('Cada rama militar necesita formations como lista.');for(const formation of branch.formations){if(formation.troops!==undefined&&(!Number.isFinite(Number(formation.troops))||Number(formation.troops)<0))throw new Error('Los efectivos de cada formación deben ser un número no negativo.');if(formation.metrics)for(const k of ['discipline','command','logistics','morale','equipment'])if(formation.metrics[k]!==undefined&&(!Number.isFinite(Number(formation.metrics[k]))||Number(formation.metrics[k])<0||Number(formation.metrics[k])>100))throw new Error('El indicador militar '+k+' debe estar entre 0 y 100.');}}draft.armedForces[id]=data;}}
  // v0.8.2: aplicar también societyCulture desde el handler activo del Editor de turno.
  if(payload.societyCulture){
   if(typeof payload.societyCulture!=='object'||Array.isArray(payload.societyCulture))throw new Error('societyCulture debe ser un objeto indexado por Estado.');
   draft.societyCulture=draft.societyCulture||{};
   for(const [rawId,data] of Object.entries(payload.societyCulture)){
    const id=(rawId==='@player'||rawId==='player'||rawId==='PLAYER')?draft.player:rawId;
    if(!nationIds.has(id))throw new Error('País desconocido en societyCulture: '+rawId+'. Usa @player para aplicar los datos al país que diriges.');
    if(!data||typeof data!=='object'||Array.isArray(data)||!Array.isArray(data.sections))throw new Error('societyCulture.'+id+' debe contener sections como lista.');
    for(const section of data.sections){
     if(!section||typeof section!=='object'||!Array.isArray(section.items))throw new Error('Cada sección de societyCulture necesita items como lista.');
     for(const item of section.items){
      if(!item||typeof item!=='object'||!item.name)throw new Error('Cada elemento de sociedad y cultura necesita name.');
      if(item.indicators&&(typeof item.indicators!=='object'||Array.isArray(item.indicators)))throw new Error('indicators debe ser un objeto de indicadores.');
     }
    }
    if(data.metrics){
     if(typeof data.metrics!=='object'||Array.isArray(data.metrics))throw new Error('metrics debe ser un objeto.');
     for(const [k,v] of Object.entries(data.metrics))if(!Number.isFinite(Number(v))||Number(v)<0||Number(v)>100)throw new Error('El indicador cultural '+k+' debe estar entre 0 y 100.');
    }
    draft.societyCulture[id]=data;
    if(!draft.societyCulture[id]||draft.societyCulture[id].sections.length!==data.sections.length)throw new Error('No se pudieron incorporar los datos de sociedad y cultura para '+id+'.');
   }
  }
  // Sistemas geopolíticos: datos de campaña independientes de la soberanía territorial.
  // regionalPower: { regions: [{ id, name, description, importance, dimensions: { military, economic, diplomatic, global } }] }
  if(payload.regionalPower!==undefined){
   if(!payload.regionalPower||typeof payload.regionalPower!=='object'||Array.isArray(payload.regionalPower)||!Array.isArray(payload.regionalPower.regions))throw new Error('regionalPower debe contener una lista regions.');
   for(const r of payload.regionalPower.regions){if(!r||typeof r!=='object'||!r.name)throw new Error('Cada región de regionalPower necesita name.');if(r.dimensions!==undefined&&(!r.dimensions||typeof r.dimensions!=='object'||Array.isArray(r.dimensions)))throw new Error('dimensions debe ser un objeto.');for(const key of ['military','economic','diplomatic','global']){const values=r.dimensions?.[key]??r[key];if(values===undefined)continue;const entries=Array.isArray(values)?values:Object.values(values);for(const entry of entries){const score=Number(typeof entry==='object'?entry.score:entry);if(!Number.isFinite(score)||score<0||score>100)throw new Error('Los niveles de poder regional deben estar entre 0 y 100.');}}}
   draft.regionalPower=JSON.parse(JSON.stringify(payload.regionalPower));
  }
  // influenceSpheres: { territories: [{ territoryName, sovereignId, status, shares: [{ countryId, recognized, effective }] }] }
  if(payload.influenceSpheres!==undefined){
   if(!payload.influenceSpheres||typeof payload.influenceSpheres!=='object'||Array.isArray(payload.influenceSpheres)||!Array.isArray(payload.influenceSpheres.territories))throw new Error('influenceSpheres debe contener una lista territories.');
   for(const t of payload.influenceSpheres.territories){if(!t||typeof t!=='object'||!(t.territoryName||t.name))throw new Error('Cada territorio de influenceSpheres necesita territoryName o name.');if(t.status&&!['open','recognized','exclusive'].includes(t.status))throw new Error('El estado de esfera debe ser open, recognized o exclusive.');if(!Array.isArray(t.shares))throw new Error('Cada territorio necesita una lista shares.');for(const share of t.shares){if(!share||typeof share!=='object'||!share.countryId)throw new Error('Cada cuota de influencia necesita countryId.');for(const key of ['recognized','effective'])if(share[key]!==undefined&&(!Number.isFinite(Number(share[key]))||Number(share[key])<0||Number(share[key])>100))throw new Error('Los porcentajes de influencia deben estar entre 0 y 100.');}}
   draft.influenceSpheres=JSON.parse(JSON.stringify(payload.influenceSpheres));
  }
  if(payload.events){if(!Array.isArray(payload.events))throw new Error('events debe ser una lista.');draft.events=draft.events||[];for(const e of payload.events){if(!e.title||!e.text)throw new Error('Cada evento necesita title y text.');draft.events.push({date:e.date||payload.date||draft.date,title:String(e.title),text:String(e.text),type:e.type||'turn',category:e.category||'',icon:e.icon||'',...(e.image?{image:String(e.image)}:{}),...(e.imageAlt?{imageAlt:String(e.imageAlt)}:{}),...(Array.isArray(e.content)?{content:e.content}:{})})}}
  if(payload.entityCreations!==undefined){if(!Array.isArray(payload.entityCreations))throw new Error('entityCreations debe ser una lista.');const ids=new Set(activeState.nations.map(n=>n.id));for(const e of payload.entityCreations){if(!e||typeof e!=='object'||Array.isArray(e)||!e.name)throw new Error('Cada entityCreations necesita al menos name.');if(e.id&&(ids.has(String(e.id))))throw new Error('Identificador de entidad duplicado: '+e.id);if(e.status&&!['sovereign','semi','non'].includes(e.status))throw new Error('status debe ser sovereign, semi o non.');const parent=e.overlord||e.parentEntityId;if(parent&&!ids.has(parent))throw new Error('La entidad superior debe existir previamente o haberse creado antes en entityCreations: '+parent);if(e.id)ids.add(String(e.id));const effectiveStatus=e.status||(e.sovereignty==='sovereign'?'sovereign':'non');if(effectiveStatus!=='sovereign'&&!parent)throw new Error('Una entidad subordinada necesita overlord o parentEntityId: '+e.name);}}
  if(payload.date&&draft.scenario.dates[draft.date]===undefined)throw new Error('No se pudo crear el estado de la nueva fecha.');
  if(payload.name)draft.name=String(payload.name);
 }catch(err){alert('No se ha aplicado el turno. '+err.message);return}
 if(payload.societyCulture){
  for(const rawId of Object.keys(payload.societyCulture)){
   const id=(rawId==='@player'||rawId==='player'||rawId==='PLAYER')?draft.player:rawId;
   if(!draft.societyCulture?.[id]||!Array.isArray(draft.societyCulture[id].sections)){
    alert('No se ha aplicado el turno: los datos de sociedad y cultura no han quedado incorporados.');return;
   }
  }
 }
 const previousEventCount=(gGame.events||[]).length;const newTurnEvents=(draft.events||[]).slice(previousEventCount);gGame=draft;gScenario=draft.scenario;gSelected=draft.selected||draft.player;
 $('turnEditorModal').classList.remove('show');launchGame();
 $('gameStatus').textContent='Turno '+gGame.turn+' aplicado · pendiente de guardar';
 if(Array.isArray(payload.entityCreations)&&payload.entityCreations.length){turnReviewQueue=newTurnEvents;turnReviewIndex=0;beginEntityCreationQueue(payload.entityCreations);}
 else if(newTurnEvents.length){turnReviewQueue=newTurnEvents;turnReviewIndex=0;showNextTurnEvent()}else{alert('Turno aplicado correctamente. Revisa los cambios y pulsa «Guardar partida» para descargar la nueva versión del archivo.')}
 $('gameStatus').textContent='Turno '+gGame.turn+' aplicado · '+newTurnEvents.length+' acontecimientos nuevos · pendiente de guardar';
};

