(()=>{const btn=document.getElementById('chronicleToggle');if(!btn)return;btn.addEventListener('click',()=>{const panel=document.querySelector('.chronicle');const collapsed=panel.classList.toggle('collapsed');btn.setAttribute('aria-expanded',String(!collapsed));btn.title=collapsed?'Mostrar cronología':'Ocultar cronología';const resize=()=>{if(window.__ltaGameMap)window.__ltaGameMap.invalidateSize({animate:false,pan:false});};requestAnimationFrame(resize);setTimeout(resize,100);setTimeout(resize,260);setTimeout(resize,440);panel.addEventListener('transitionend',resize,{once:true});});})();

(function(){const tip=document.createElement('div');tip.className='ui-floating-tooltip';document.body.appendChild(tip);let active=null;function show(el){const text=el.getAttribute('data-tooltip');if(!text)return;active=el;tip.textContent=text;tip.style.display='block';place()}function place(){if(!active)return;const r=active.getBoundingClientRect(),w=tip.offsetWidth,h=tip.offsetHeight;let x=r.left+r.width/2-w/2,y=r.top-h-10;if(y<8)y=r.bottom+10;if(y+h>innerHeight-8)y=Math.max(8,innerHeight-h-8);x=Math.max(8,Math.min(innerWidth-w-8,x));tip.style.left=x+'px';tip.style.top=y+'px'}document.addEventListener('mouseover',e=>{const el=e.target.closest('[data-tooltip]');if(el)show(el)});document.addEventListener('mouseout',e=>{if(active&&(!e.relatedTarget||!active.contains(e.relatedTarget))){active=null;tip.style.display='none'}});window.addEventListener('scroll',place,true);window.addEventListener('resize',place)})();
